    function run(uint amount, uint future) public payable {
        require(future > 0);
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Set pastBlockTime to a deterministic future timestamp using a successful call,
        // then test that the next call with the same timestamp must revert.
        uint prior = c.pastBlockTime();
        uint target = prior + future;
        require(target > prior);

        // Need the first call to have block.timestamp == target; cannot control block.timestamp,
        // so we instead first assert the general invariant on the current timestamp after reading it.
        // Use two calls only if timestamp is strictly increasing.
        bool firstReverted;
        try c.fallback{value: amount}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint afterFirst = c.pastBlockTime();
        if (!firstReverted) {
            // successful call must have set pastBlockTime to the block timestamp
            // and any later call at the same timestamp must revert
            assert(afterFirst >= prior);
        }

        // The general rule: if a 10 ether call succeeds at timestamp t, then a second call
        // at the same timestamp fails because pastBlockTime was not advanced past t.
        bool secondReverted;
        try c.fallback{value: amount}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(firstReverted || (afterFirst == c.pastBlockTime() ? secondReverted : true));
    }

    receive() external payable {}
}

