contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 ts) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Set up pastBlockTime to a known value before the deciding call.
        // Use a time <= ts so we can test the case where the call should succeed.
        // Since block.timestamp is controlled by the EVM and will be >= ts,
        // requiring ts <= block.timestamp makes pastBlockTime <= block.timestamp.
        c.fallback{value: amount}();
        uint256 oldPast = c.pastBlockTime();

        // Second call with the same amount to create a deterministic state transition:
        // before this call pastBlockTime is whatever the first call made it, and
        // it will be strictly less than block.timestamp in a normal EVM execution
        // unless the block timestamp is reused. To keep the rule general and
        // avoid relying on block.timestamp being fresh, first force a timestamp
        // race would be unsafe. Instead, prefix the deciding call with a known
        // successful call if the first one reverted, but only using top-level calls.
        // The property we assert is: after a successful fallback call that sends
        // exactly 10 ether, the contract's pastBlockTime equals the block timestamp
        // at the time of the call, which is at least oldPast.

        // Make the deciding call: send exactly 10 ether again.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 newPast = c.pastBlockTime();

        // General rule: the fallback must revert if the timestamp precondition
        // is not met. If it did not revert, then the timestamp precondition must
        // have been met and pastBlockTime must have been updated to a value
        // strictly greater than the previous pastBlockTime. Since block.timestamp
        // cannot decrease, the only way this can fail is if the contract allowed
        // a successful call without updating the timestamp or with a timestamp
        // not greater than the old one. We express this as: either it reverted,
        // or the new pastBlockTime is greater than oldPast.
        // Note: oldPast was read after the first successful call, so oldPast >= ts.
        assert(reverted || newPast > oldPast);
    }

    receive() external payable {}
}

