contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        // Precondition: we attempt to send exactly 10 ether in the call below.
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Ensure that block.timestamp is strictly greater than the current stored pastBlockTime.
        // Since the test contract is the deployer/only caller, no prior fallback call has occurred,
        // so pastBlockTime starts at 0 and block.timestamp is always > 0.

        uint256 beforeBlockTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBlockTime = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;

        // General rule: the call must succeed, pastBlockTime must become the current timestamp
        // (strictly greater than the old value), and the contract balance must increase by the
        // sent amount unless the block number is divisible by 15, in which case the entire
        // balance (including the sent amount) is transferred to the sender.
        assert(
            !reverted &&
            afterBlockTime == block.timestamp &&
            afterBlockTime > beforeBlockTime &&
            (
                (block.number % 15 == 0 && afterBalance == 0) ||
                (block.number % 15 != 0 && afterBalance == beforeBalance + amount)
            )
        );
    }

    receive() external payable {}
}

